// Push Notification Service Worker
// This file is imported by the main service worker generated by next-pwa

self.addEventListener('push', function (event) {
  if (!event.data) {
    console.log('Push event but no data')
    return
  }

  try {
    const payload = event.data.json()

    const options = {
      body: payload.body,
      icon: payload.icon || '/icons/icon-192x192.png',
      badge: payload.badge || '/icons/icon-72x72.png',
      image: payload.image,
      tag: payload.tag || 'default',
      renotify: true,
      requireInteraction: false,
      data: {
        url: payload.url || '/',
        ...payload.data,
      },
      actions: payload.actions || [],
      vibrate: [100, 50, 100],
    }

    event.waitUntil(self.registration.showNotification(payload.title, options))
  } catch (error) {
    console.error('Error processing push event:', error)
  }
})

self.addEventListener('notificationclick', function (event) {
  event.notification.close()

  const url = event.notification.data?.url || '/'

  // Handle action button clicks
  if (event.action) {
    // Custom action handling can be added here
    console.log('Notification action clicked:', event.action)
  }

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function (clientList) {
      // Check if there's already an open window
      for (const client of clientList) {
        if (client.url.includes(self.location.origin) && 'focus' in client) {
          client.navigate(url)
          return client.focus()
        }
      }
      // If no window is open, open a new one
      if (clients.openWindow) {
        return clients.openWindow(url)
      }
    })
  )
})

self.addEventListener('notificationclose', function (event) {
  // Track notification dismissal if needed
  console.log('Notification closed:', event.notification.tag)
})

// Handle push subscription change (e.g., when browser refreshes keys)
self.addEventListener('pushsubscriptionchange', function (event) {
  event.waitUntil(
    self.registration.pushManager.subscribe(event.oldSubscription.options).then(function (subscription) {
      // Re-subscribe on the server
      return fetch('/api/push/subscribe', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          endpoint: subscription.endpoint,
          keys: {
            p256dh: btoa(String.fromCharCode.apply(null, new Uint8Array(subscription.getKey('p256dh')))),
            auth: btoa(String.fromCharCode.apply(null, new Uint8Array(subscription.getKey('auth')))),
          },
        }),
      })
    })
  )
})
